"""Read-only: for each evidence source, what the repository retains of it (OD-23 fact-finding).
Joins retrieval-log manifest lines to sources by ref_id, URL or DOI. Classes, best first:
  text  = a committed pdf/html/txt/xml/doc artefact on disk; images = only png on disk;
  manifest-only = a manifest line whose artefact file is not on disk (or only a json API payload);
  nothing = no manifest line found. Heuristic join; a source fetched under another URL is missed.
Usage: python3 -I retained_census.py <repo root>"""
import sqlite3, sys, json, pathlib, collections, re
root = pathlib.Path(sys.argv[1])
c = sqlite3.connect(f"file:{root/'data/guidebook.db'}?mode=ro", uri=True)
cols = [r[1] for r in c.execute("pragma table_info(evidence_sources)")]
urlcols = [x for x in ("url", "doi", "pdf_url", "source_url") if x in cols]
src = {r[0]: [v for v in r[1:] if v] for r in c.execute(f"select ref_id, {', '.join(urlcols)} from evidence_sources")}
def norm(u): return re.sub(r"^https?://(dx\.)?(doi\.org/)?|/$", "", u.strip().lower())
idx = collections.defaultdict(list)
for m in root.glob("retrieval-log/*/manifest.jsonl"):
    for line in m.read_text(encoding="utf-8").splitlines():
        try: d = json.loads(line)
        except ValueError: continue
        art = m.parent / (d.get("artefact") or "")
        rec = (art.suffix.lower(), art.is_file() and bool(d.get("artefact")))
        if d.get("ref_id"): idx[("ref", d["ref_id"])].append(rec)
        if d.get("url"): idx[("url", norm(d["url"]))].append(rec)
TEXT = {".pdf", ".html", ".htm", ".txt", ".xml", ".doc", ".docx"}
cls = collections.Counter(); per = {}
for ref, keys in src.items():
    recs = idx.get(("ref", ref), []) + [r for k in keys for r in idx.get(("url", norm(k)), [])]
    on_disk = {s for s, ok in recs if ok}
    k = ("text" if on_disk & TEXT else "images" if ".png" in on_disk else
         "manifest-only" if recs else "nothing")
    cls[k] += 1; per[ref] = k
print("EXAMINED:", len(src), "sources; join columns:", urlcols)
for k in ("text", "images", "manifest-only", "nothing"): print(f"  {k}: {cls[k]}")
used = {r[0] for r in c.execute("select distinct ref_id from source_value_extractions")}
print("of sources with at least one extraction:", collections.Counter(per[r] for r in used if r in per))
scans = [r[1] for r in c.execute("pragma table_info(source_scans)")] if c.execute("select 1 from sqlite_master where name='source_scans'").fetchone() else []
if scans: print("source_scans rows:", c.execute("select count(*), count(distinct ref_id) from source_scans").fetchone())
PY
